use std::{
    io,
    pin::Pin,
    sync::{Arc, Mutex},
    task::{Context, Poll, ready},
};
use tokio::io::{AsyncRead, AsyncWrite, ReadBuf};

#[derive(Clone, Copy, Default)]
pub(super) struct Stats {
    pub(super) body_bytes: u64,
    pub(super) compressed_messages: u64,
}

/// Observes only outbound frame headers generated by the codec.
#[derive(Default)]
struct FrameMeter {
    header: [u8; 10],
    header_len: usize,
    skip: u64,
    stats: Stats,
}

impl FrameMeter {
    fn observe(&mut self, mut bytes: &[u8]) {
        while !bytes.is_empty() {
            if self.skip > 0 {
                let size = self.skip.min(bytes.len() as u64);
                bytes = &bytes[size as usize..];
                self.skip -= size;
                continue;
            }
            let header_size = if self.header_len < 2 {
                2
            } else {
                match self.header[1] & 0x7f {
                    126 => 4,
                    127 => 10,
                    _ => 2,
                }
            };
            let len = (header_size - self.header_len).min(bytes.len());
            self.header[self.header_len..self.header_len + len].copy_from_slice(&bytes[..len]);
            bytes = &bytes[len..];
            self.header_len += len;
            if self.header_len < header_size {
                continue;
            }
            let size = match self.header[1] & 0x7f {
                126 if self.header_len < 4 => continue,
                127 if self.header_len < 10 => continue,
                126 => u16::from_be_bytes([self.header[2], self.header[3]]) as u64,
                127 => u64::from_be_bytes(self.header[2..].try_into().expect("eight length bytes")),
                size => u64::from(size),
            };
            if matches!(self.header[0] & 0x0f, 0..=2) {
                self.stats.body_bytes += size;
                self.stats.compressed_messages += u64::from(self.header[0] & 0x40 != 0);
            }
            // Never copy payload or mask bytes into the observation.
            self.skip = size + if self.header[1] & 0x80 != 0 { 4 } else { 0 };
            self.header_len = 0;
        }
    }
}

pub(super) struct Meter(Arc<Mutex<FrameMeter>>);

impl Meter {
    pub(super) fn stats(&self) -> Stats {
        crate::poison::mutex(&self.0).stats
    }
}

pub(super) struct MeteredIo {
    inner: reqwest::Upgraded,
    meter: Arc<Mutex<FrameMeter>>,
}

impl MeteredIo {
    pub(super) fn new(inner: reqwest::Upgraded) -> (Self, Meter) {
        let meter = Arc::new(Mutex::new(FrameMeter::default()));
        (
            Self {
                inner,
                meter: meter.clone(),
            },
            Meter(meter),
        )
    }
}

impl AsyncRead for MeteredIo {
    fn poll_read(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        Pin::new(&mut self.inner).poll_read(cx, buf)
    }
}

impl AsyncWrite for MeteredIo {
    fn poll_write(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        bytes: &[u8],
    ) -> Poll<io::Result<usize>> {
        let written = ready!(Pin::new(&mut self.inner).poll_write(cx, bytes))?;
        crate::poison::mutex(&self.meter).observe(&bytes[..written]);
        Poll::Ready(Ok(written))
    }

    fn poll_flush(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.inner).poll_flush(cx)
    }

    fn poll_shutdown(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        Pin::new(&mut self.inner).poll_shutdown(cx)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frame_meter_counts_payload_only_across_partial_writes() {
        let mut meter = FrameMeter::default();
        let mut wire = vec![0x41, 128 | 126, 0, 126, 1, 2, 3, 4]; // compressed text start
        wire.extend([0; 126]);
        wire.extend([0x89, 128 | 1, 1, 2, 3, 4, 0]); // ping
        wire.extend([0x80, 128 | 2, 1, 2, 3, 4, 0, 0]); // final continuation
        wire.extend([0x81, 0x80, 1, 2, 3, 4]); // empty uncompressed text
        for chunk in wire.chunks(3) {
            meter.observe(chunk);
        }
        assert_eq!(meter.stats.body_bytes, 128);
        assert_eq!(meter.stats.compressed_messages, 1);
        assert_eq!(meter.header_len, 0);
        assert_eq!(meter.skip, 0);
    }
}
